import sys
from collections import defaultdict

def captainAmerica(N, M, V):
    adj = defaultdict(list)
    rev_adj = defaultdict(list)

    for u, v in V:
        adj[u].append(v)
        rev_adj[v].append(u)

    def dfs(graph, node, visited):
        stack = [node]
        while stack:
            curr = stack.pop()
            if not visited[curr]:
                visited[curr] = True
                for neighbor in graph[curr]:
                    if not visited[neighbor]:
                        stack.append(neighbor)

    order = []
    visited = [False] * (N + 1)

    for i in range(1, N + 1):
        if not visited[i]:
            stack = [(i, 0)]
            while stack:
                node, idx = stack[-1]
                if not visited[node]:
                    visited[node] = True
                if idx < len(adj[node]):
                    neighbor = adj[node][idx]
                    stack[-1] = (node, idx + 1)
                    if not visited[neighbor]:
                        stack.append((neighbor, 0))
                else:
                    order.append(node)
                    stack.pop()

    comp = [-1] * (N + 1)
    comp_count = 0

    visited = [False] * (N + 1)
    for i in range(N - 1, -1, -1):
        node = order[i]
        if not visited[node]:
            stack = [node]
            visited[node] = True
            comp[node] = comp_count
            while stack:
                curr = stack.pop()
                for neighbor in rev_adj[curr]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        comp[neighbor] = comp_count
                        stack.append(neighbor)
            comp_count += 1

    has_outgoing = [False] * comp_count
    for u in range(1, N + 1):
        for v in adj[u]:
            if comp[u] != comp[v]:
                has_outgoing[comp[u]] = True

    sink_comp = None
    for c in range(comp_count):
        if not has_outgoing[c]:
            if sink_comp is not None:
                return 0
            sink_comp = c

    if sink_comp is None:
        return 0

    count = 0
    for i in range(1, N + 1):
        comp[i]
        if comp[i] == sink_comp:
            count += 1

    return count

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))

        V = []
        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            V.append([u, v])

        result = captainAmerica(N, M, V)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
